    51			return NULL;
    52		}
    53	
    54		/* Scan the slots for the first available one, mark it used and return
    55		 * the payload address (the byte right after the availability flag). */
    56		for (i = 0; i < buf->numAllBlk; i++)
    57		{
    58			blkPtr = buf->data + i * (buf->blkSize + 1);
    59			if (*blkPtr == BLOCK_AVAILABLE)
    60			{
    61				*blkPtr = BLOCK_UNAVAILABLE;
    62				buf->numFreeBlk--;
    63				return blkPtr + 1;
    64			}
    65		}
    66	
    67		perror("Buffer Overflows!\n");
    68		return NULL;
    69	}
    70	
    71	void freeBlockInBuffer(unsigned char *blk, Buffer *buf)
    72	{
    73		if (blk == NULL || buf == NULL)
    74			return;
    75	
    76		/* The availability flag sits one byte in front of the payload. */
    77		unsigned char *blkPtr = blk - 1;
    78	
    79		if (*blkPtr == BLOCK_AVAILABLE) /* already free: do not double count */
    80			return;
    81	
    82		*blkPtr = BLOCK_AVAILABLE;
    83		memset(blk, 0, buf->blkSize);
    84		buf->numFreeBlk++;
    85	}
    86	
    87	int dropBlockOnDisk(unsigned int addr)
    88	{
    89		char filename[40];
    90	
    91		sprintf(filename, "%d.blk", addr);
    92	
    93		if (remove(filename) == -1)
    94		{
    95			perror("Dropping Block Fails!\n");
    96			return -1;
    97		}
    98	
    99		return 0;
   100	}
   101	
   102	unsigned char *readBlockFromDisk(unsigned int addr, Buffer *buf)
   103	{
   104		FILE *fp;
   105		char filename[40];
   106		unsigned char *blkPtr;
   107	
   108		if (buf == NULL)
   109			return NULL;
   110	
   111		if ((blkPtr = getNewBlockInBuffer(buf)) == NULL)
   112			return NULL;
   113	
   114		sprintf(filename, "%d.blk", addr);
   115	
   116		if ((fp = fopen(filename, "rb")) == NULL)
   117		{
   118			perror("Reading Block Fails!\n");
   119			freeBlockInBuffer(blkPtr, buf);
   120			return NULL;
   121		}
   122	
   123		fread(blkPtr, buf->blkSize, 1, fp);
   124		fclose(fp);
   125	
   126		buf->numIO++; /* one more I/O */
   127	
   128		return blkPtr;
   129	}
   130	
   131	int writeBlockToDisk(unsigned char *blkPtr, unsigned int addr, Buffer *buf)
   132	{
   133		FILE *fp;
   134		char filename[40];
   135	
   136		if (blkPtr == NULL || buf == NULL)
   137			return -1;
   138	
   139		sprintf(filename, "%d.blk", addr);
   140	
   141		if ((fp = fopen(filename, "wb+")) == NULL)
   142		{
   143			perror("Writing Block Fails!\n");
   144			return -1;
   145		}
   146	
   147		if (fwrite(blkPtr, buf->blkSize, 1, fp) == 0)
   148		{
   149			perror("Writing Block Fails!\n");
   150			fclose(fp);
   151			return -1;
   152		}
   153	
   154		fclose(fp);
   155	
   156		/* The block has been flushed, hand its slot back to the buffer. */
   157		freeBlockInBuffer(blkPtr, buf);
   158	
   159		buf->numIO++; /* one more I/O */
   160	
   161		return 0;
   162	}
