     5	#include <string.h>
     6	#include <iostream>
     7	#include "blkio.h"
     8	#include "file.h"
     9	
    10	using namespace std;
    11	
    12	/* State of the buffered result writer.
    13	 *
    14	 * Result tuples are accumulated in a single block of the buffer. As soon as
    15	 * the next tuple would no longer fit (the last PTR_SIZE bytes of every block
    16	 * are reserved for the address of the following block) the block is flushed
    17	 * to disk and a fresh one is taken from the buffer.
    18	 *
    19	 * pushToWrite(buf, NULL, 0, addr, true)        -> start a new result at addr
    20	 * pushToWrite(buf, tuple, sizeof(tuple), addr) -> append one tuple
    21	 * pushToWrite(buf, NULL, 0, addr, false, true) -> flush the last block
    22	 */
    23	static unsigned char *writeBlk = NULL; /* block currently being filled */
    24	static size_t writeOff = 0;            /* bytes already used in writeBlk */
    25	static unsigned int writeAddr = 0;     /* disk address of writeBlk */
    26	
    27	void pushToWrite(Buffer *buf, unsigned char *source, size_t size, unsigned int addr, bool reset, bool push)
    28	{
    29		if (reset)
    30		{
    31			/* The buffer the previous result was written with may already be
    32			 * gone, so never touch writeBlk here - just forget about it. */
    33			writeBlk = NULL;
    34			writeOff = 0;
    35			writeAddr = addr;
    36			return;
    37		}
    38	
    39		if (buf == NULL)
    40			return;
    41	
    42		const size_t capacity = buf->blkSize - PTR_SIZE; /* usable payload bytes */
    43	
    44		if (source != NULL && size > 0)
    45		{
    46			if (writeBlk == NULL)
    47			{
    48				if ((writeBlk = getNewBlockInBuffer(buf)) == NULL)
    49					return;
    50				memset(writeBlk, 0, buf->blkSize);
    51				writeOff = 0;
    52			}
    53	
    54			if (writeOff + size > capacity)
    55			{
    56				/* Full: chain this block to the next one and flush it. */
    57				unsigned int next = writeAddr + 1;
    58				memcpy(writeBlk + buf->blkSize - PTR_SIZE, &next, PTR_SIZE);
    59				writeBlockToDisk(writeBlk, writeAddr, buf);
    60				writeAddr = next;
    61	
    62				if ((writeBlk = getNewBlockInBuffer(buf)) == NULL)
    63				{
    64					writeOff = 0;
    65					return;
    66				}
    67				memset(writeBlk, 0, buf->blkSize);
    68				writeOff = 0;
    69			}
    70	
    71			memcpy(writeBlk + writeOff, source, size);
    72			writeOff += size;
    73		}
    74	
    75		if (push && writeBlk != NULL)
    76		{
    77			/* Last block of the result: the next-block address stays 0. */
    78			unsigned int next = 0;
    79			memcpy(writeBlk + buf->blkSize - PTR_SIZE, &next, PTR_SIZE);
    80			writeBlockToDisk(writeBlk, writeAddr, buf);
    81			writeAddr++;
    82			writeBlk = NULL;
    83			writeOff = 0;
    84		}
    85	}
    86	
    87	void readTuplesFromBlock(unsigned char *blk, Relation *R)
    88	{
    89		if (blk == NULL || R == NULL)
    90			return;
    91	
    92		/* A relation block stores TUPLE_PER_BLK tuples of two 4-byte integers,
    93		 * followed by the address of the next block of the relation. */
    94		for (int i = 0; i < TUPLE_PER_BLK; i++)
    95		{
    96			memcpy(&R[i].attr1, blk + i * 2 * PTR_SIZE, PTR_SIZE);
    97			memcpy(&R[i].attr2, blk + i * 2 * PTR_SIZE + PTR_SIZE, PTR_SIZE);
    98		}
    99	}
   100	
   101	void output(Buffer *buf, unsigned int addr, int attr1, int attr2, int attr3)
   102	{
   103		Relation3 tuple = { attr1, attr2, attr3 };
   104	
   105		cout << "(" << attr1 << ", " << attr2 << ", " << attr3 << ")" << endl;
   106	
   107		/* A join result tuple carries three attributes, so only
   108		 * (blkSize - PTR_SIZE) / (3 * PTR_SIZE) = 5 of them fit into one block. */
   109		pushToWrite(buf, (unsigned char *)&tuple, sizeof(Relation3), addr);
   110	}
   111	
   112	/* State of the hash partition writer.
   113	 *
   114	 * One block per bucket is kept in the buffer (BUCKET_NUM = 6 blocks, which
   115	 * still leaves room for the block that is being scanned). A partition block
   116	 * looks like
   117	 *
   118	 *   [ number of tuples : 4 ][ up to HASH_PER_BLK tuples : 8 each ] ...
   119	 *   ... [ address of the next block of this bucket : 4 (last 4 bytes) ]
   120	 *
   121	 * Bucket b of the relation starting at addr is chained from block
   122	 * addr + b * (OFFSET / BUCKET_NUM), which keeps the buckets of R and of S
   123	 * inside their own OFFSET-sized address range.
   124	 */
   125	static unsigned char *hashBlk[BUCKET_NUM] = { NULL };
   126	static int hashCnt[BUCKET_NUM] = { 0 };
   127	static unsigned int hashAddr[BUCKET_NUM] = { 0 };
   128	
   129	static unsigned int bucketStride()
   130	{
   131		return OFFSET / BUCKET_NUM;
   132	}
   133	
   134	/* Flush one bucket block, chaining it to next. */
   135	static void flushHashBlock(Buffer *buf, int b, unsigned int next)
   136	{
   137		memcpy(hashBlk[b], &hashCnt[b], PTR_SIZE);
   138		memcpy(hashBlk[b] + buf->blkSize - PTR_SIZE, &next, PTR_SIZE);
   139		writeBlockToDisk(hashBlk[b], hashAddr[b], buf);
   140		hashBlk[b] = NULL;
   141		hashCnt[b] = 0;
   142	}
   143	
   144	void pushHashToWrite(Buffer *buf, Relation *R, unsigned int addr, bool reset, bool push)
   145	{
   146		if (reset)
   147		{
   148			/* Forget every pending block: the buffer they belong to may be gone. */
   149			for (int b = 0; b < BUCKET_NUM; b++)
   150			{
   151				hashBlk[b] = NULL;
   152				hashCnt[b] = 0;
   153				hashAddr[b] = addr + b * bucketStride();
   154			}
   155			return;
   156		}
   157	
   158		if (buf == NULL)
   159			return;
   160	
   161		if (R != NULL)
   162		{
   163			int b = R->attr1 % BUCKET_NUM; /* hash function: key mod BUCKET_NUM */
   164	
   165			if (hashBlk[b] == NULL)
   166			{
   167				if ((hashBlk[b] = getNewBlockInBuffer(buf)) == NULL)
   168					return;
   169				memset(hashBlk[b], 0, buf->blkSize);
   170				hashCnt[b] = 0;
   171			}
   172	
   173			if (hashCnt[b] >= HASH_PER_BLK)
   174			{
   175				/* Bucket block is full: chain it to the next block of the bucket. */
   176				unsigned int next = hashAddr[b] + 1;
   177				flushHashBlock(buf, b, next);
   178				hashAddr[b] = next;
   179	
   180				if ((hashBlk[b] = getNewBlockInBuffer(buf)) == NULL)
   181					return;
   182				memset(hashBlk[b], 0, buf->blkSize);
   183				hashCnt[b] = 0;
   184			}
   185	
   186			memcpy(hashBlk[b] + PTR_SIZE + hashCnt[b] * 2 * PTR_SIZE, &R->attr1, PTR_SIZE);
   187			memcpy(hashBlk[b] + PTR_SIZE + hashCnt[b] * 2 * PTR_SIZE + PTR_SIZE, &R->attr2, PTR_SIZE);
   188			hashCnt[b]++;
   189			memcpy(hashBlk[b], &hashCnt[b], PTR_SIZE);
   190		}
   191	
   192		if (push)
   193		{
   194			/* Write the last block of every bucket. Empty buckets get an empty
   195			 * block so that every bucket chain can be opened unconditionally. */
   196			for (int b = 0; b < BUCKET_NUM; b++)
   197			{
   198				if (hashBlk[b] == NULL)
   199				{
   200					if ((hashBlk[b] = getNewBlockInBuffer(buf)) == NULL)
   201						continue;
   202					memset(hashBlk[b], 0, buf->blkSize);
   203					hashCnt[b] = 0;
   204				}
   205				flushHashBlock(buf, b, 0);
   206			}
   207		}
   208	}
   209	
   210	int readHashFromBlock(unsigned char *blk, Relation *R)
   211	{
   212		int num = 0;
   213	
   214		if (blk == NULL || R == NULL)
   215			return 0;
   216	
   217		/* The first 4 bytes of a partition block hold the number of tuples. */
   218		memcpy(&num, blk, PTR_SIZE);
   219		if (num < 0)
   220			num = 0;
   221		if (num > HASH_PER_BLK)
   222			num = HASH_PER_BLK;
   223	
   224		for (int i = 0; i < num; i++)
   225		{
   226			memcpy(&R[i].attr1, blk + PTR_SIZE + i * 2 * PTR_SIZE, PTR_SIZE);
   227			memcpy(&R[i].attr2, blk + PTR_SIZE + i * 2 * PTR_SIZE + PTR_SIZE, PTR_SIZE);
   228		}
   229	
   230		return num;
   231	}

