    14	/* Projection with duplicate elimination:
    15	 *
    16	 *   select distinct A from R
    17	 *
    18	 * R is first sorted on A, which brings equal values of A next to each other;
    19	 * a single scan of the sorted relation then keeps one tuple per group. Only
    20	 * one block of the sorted relation and one block of the result are needed in
    21	 * the buffer at a time.
    22	 *
    23	 * The projected values are written to the chain of blocks starting at
    24	 * PROJECT_RET_ADDR. The return value is the number of distinct values of A,
    25	 * or -1 on failure.
    26	 */
    27	int project(Buffer *buf)
    28	{
    29		if (buf == NULL)
    30			return -1;
    31	
    32		/* --------- preparation: sort R so that duplicates become adjacent --------- */
    33		if (mergeSort(buf, SORT_R) < 0)
    34			return -1;
    35	
    36		pushToWrite(buf, NULL, 0, PROJECT_RET_ADDR, true);
    37	
    38		cout << "select distinct A from R:" << endl;
    39	
    40		/* --------- scan the sorted relation and keep every value of A once --------- */
    41		Relation tuples[TUPLE_PER_BLK];
    42		unsigned int addr = MERGE_R_RET_ADDR;
    43		int num = 0;    /* number of distinct values found so far */
    44		int last = 0;   /* the value emitted last; 0 never occurs in R */
    45	
    46		while (addr != 0)
    47		{
    48			unsigned char *blk = readBlockFromDisk(addr, buf);
    49			if (blk == NULL)
    50				return -1;
    51	
    52			readTuplesFromBlock(blk, tuples);
    53			memcpy(&addr, blk + buf->blkSize - PTR_SIZE, PTR_SIZE); /* next block */
    54			freeBlockInBuffer(blk, buf);
    55	
    56			for (int j = 0; j < TUPLE_PER_BLK; j++)
    57			{
    58				if (tuples[j].attr1 == 0) /* unused tuple slot */
    59					continue;
    60				if (num > 0 && tuples[j].attr1 == last) /* duplicate of A */
    61					continue;
    62	
    63				cout << "(" << tuples[j].attr1 << ")" << endl;
    64				/* The projection keeps one attribute, so a result tuple is a
    65				 * single integer. */
    66				pushToWrite(buf, (unsigned char *)&tuples[j].attr1, PTR_SIZE, PROJECT_RET_ADDR);
    67				last = tuples[j].attr1;
    68				num++;
    69			}
    70		}
    71	
    72		/* Write the last, partially filled block of the result. */
    73		pushToWrite(buf, NULL, 0, PROJECT_RET_ADDR, false, true);
    74	
    75		cout << "Total number of result tuples: " << num << endl;
    76		cout << "Total number of I/O's: " << buf->numIO << endl;
    77	
    78		return num;
    79	}

