     4	
     5	#include <iostream>
     6	#include <string.h>
     7	#include <algorithm>
     8	#include <cmath>
     9	#include "mergeSort.h"
    10	#include "file.h"
    11	#include "blkio.h"
    12	
    13	using namespace std;
    14	
    15	/* Number of blocks the buffer can hold at the same time, i.e. M. */
    16	#define MAX_BLK_IN_BUF (BUF_SIZE / (BLK_SIZE + 1))
    17	
    18	/* Order tuples on the first attribute (the sort / join key). The second
    19	 * attribute breaks ties so that the produced order is deterministic. */
    20	static bool tupleLess(const Relation &a, const Relation &b)
    21	{
    22		if (a.attr1 != b.attr1)
    23			return a.attr1 < b.attr1;
    24		return a.attr2 < b.attr2;
    25	}
    26	
    27	/* One sorted run while it takes part in the final merge. Exactly one block of
    28	 * every run is kept in the buffer, which is what makes the merge a multi-way
    29	 * merge that fits into M blocks: (number of runs) + 1 output block. */
    30	struct Run
    31	{
    32		unsigned char *blk;            /* block of the run held in the buffer */
    33		Relation tuple[TUPLE_PER_BLK]; /* the tuples stored in that block */
    34		int cnt;                       /* number of valid tuples in the block */
    35		int pos;                       /* next tuple of the block to consume */
    36		unsigned int next;             /* address of the next block of the run */
    37	};
    38	
    39	/* Read one block of a run into the buffer and decode it. */
    40	static bool loadRunBlock(Buffer *buf, Run &run, unsigned int addr)
    41	{
    42		if ((run.blk = readBlockFromDisk(addr, buf)) == NULL)
    43			return false;
    44	
    45		readTuplesFromBlock(run.blk, run.tuple);
    46	
    47		run.cnt = 0;
    48		while (run.cnt < TUPLE_PER_BLK && run.tuple[run.cnt].attr1 != 0)
    49			run.cnt++; /* 0 marks an unused tuple slot */
    50		run.pos = 0;
    51		memcpy(&run.next, run.blk + buf->blkSize - PTR_SIZE, PTR_SIZE);
    52	
    53		return true;
    54	}
    55	
    56	/* Whether the head of the run still holds an unconsumed tuple. */
    57	static bool runHasTuple(const Run &run)
    58	{
    59		return run.blk != NULL && run.pos < run.cnt;
    60	}
    61	
    62	/* Release an exhausted block and pull the next block of the run in, so that
    63	 * the head of the run is a tuple again (unless the run is over). */
    64	static bool refillRun(Buffer *buf, Run &run)
    65	{
    66		while (run.blk != NULL && run.pos >= run.cnt)
    67		{
    68			unsigned int next = run.next;
    69	
    70			freeBlockInBuffer(run.blk, buf);
    71			run.blk = NULL;
    72			run.cnt = run.pos = 0;
    73	
    74			if (next == 0) /* the chain of the run ends here */
    75				break;
    76			if (!loadRunBlock(buf, run, next))
    77				return false;
    78		}
    79	
    80		return true;
    81	}
    82	
    83	/* Two-pass multi-way merge sort of R (choice == SORT_R) or S (choice == SORT_S)
    84	 * on the first attribute.
    85	 *
    86	 * pass 1: every segment of M consecutive blocks is sorted in main memory and
    87	 *         written back as a sorted run,
    88	 * pass 2: the heads of all runs are merged into the globally sorted relation.
    89	 *
    90	 * The sorted relation is left on the disk as a chain of blocks starting at
    91	 * MERGE_R_RET_ADDR / MERGE_S_RET_ADDR. The return value is the number of I/O's
    92	 * performed by the sort, or -1 on failure.
    93	 */
    94	int mergeSort(Buffer *buf, bool choice)
    95	{
    96		if (buf == NULL)
    97			return -1;
    98	
    99		const unsigned int srcAddr = (choice == SORT_R) ? R_ADDR : S_ADDR;
   100		const int srcBlkNum = (choice == SORT_R) ? R_BLK_NUM : S_BLK_NUM;
   101		const unsigned int segAddr = (choice == SORT_R) ? MERGE_R_SEG_ADDR : MERGE_S_SEG_ADDR;
   102		const unsigned int retAddr = (choice == SORT_R) ? MERGE_R_RET_ADDR : MERGE_S_RET_ADDR;
   103	
   104		int M = (int)buf->numAllBlk; /* blocks available in the buffer */
   105		if (M > MAX_BLK_IN_BUF)
   106			M = MAX_BLK_IN_BUF;
   107		if (M < 2)
   108			return -1;
   109	
   110		const int segNum = (srcBlkNum + M - 1) / M; /* number of sorted runs */
   111		const unsigned long startIO = buf->numIO;
   112	
   113		Relation seg[MAX_BLK_IN_BUF * TUPLE_PER_BLK]; /* one segment in memory */
   114		Relation tuples[TUPLE_PER_BLK];
   115	
   116		/* ---------------- pass 1: generate the sorted runs ---------------- */
   117		for (int s = 0; s < segNum; s++)
   118		{
   119			int num = 0; /* tuples of the current segment */
   120	
   121			/* Read the (at most) M blocks of the segment. Every block is decoded
   122			 * and released right away, so the buffer never runs out of blocks. */
   123			for (int i = 0; i < M && s * M + i < srcBlkNum; i++)
   124			{
   125				unsigned char *blk = readBlockFromDisk(srcAddr + s * M + i, buf);
   126				if (blk == NULL)
   127					return -1;
   128	
   129				readTuplesFromBlock(blk, tuples);
   130				for (int j = 0; j < TUPLE_PER_BLK; j++)
   131					if (tuples[j].attr1 != 0) /* 0 marks an unused tuple slot */
   132						seg[num++] = tuples[j];
   133	
   134				freeBlockInBuffer(blk, buf);
   135			}
   136	
   137			/* Sort the segment in main memory ... */
   138			sort(seg, seg + num, tupleLess);
   139	
   140			/* ... and write it back as run number s. Every run is a chain of its
   141			 * own, which is why consecutive runs are M blocks apart on the disk. */
   142			pushToWrite(buf, NULL, 0, segAddr + s * M, true);
   143			for (int i = 0; i < num; i++)
   144				pushToWrite(buf, (unsigned char *)&seg[i], sizeof(Relation), segAddr + s * M);
   145			pushToWrite(buf, NULL, 0, segAddr + s * M, false, true);
   146		}
   147	
   148		/* ------------- pass 2: merge the heads of all the runs ------------- */
   149		if (segNum > M - 1) /* one block of the buffer is needed for the output */
   150			return -1;
   151	
   152		Run run[MAX_BLK_IN_BUF];
   153		for (int s = 0; s < segNum; s++)
   154		{
   155			run[s].blk = NULL;
   156			run[s].cnt = run[s].pos = 0;
   157			run[s].next = 0;
   158			if (!loadRunBlock(buf, run[s], segAddr + s * M) || !refillRun(buf, run[s]))
   159				return -1;
   160		}
   161	
   162		pushToWrite(buf, NULL, 0, retAddr, true);
   163	
   164		while (true)
   165		{
   166			/* Pick the smallest of the heads of the runs. */
   167			int best = -1;
   168			for (int s = 0; s < segNum; s++)
   169			{
   170				if (!runHasTuple(run[s]))
   171					continue;
   172				if (best < 0 || tupleLess(run[s].tuple[run[s].pos], run[best].tuple[run[best].pos]))
   173					best = s;
   174			}
   175	
   176			if (best < 0) /* every run has been consumed */
   177				break;
   178	
   179			pushToWrite(buf, (unsigned char *)&run[best].tuple[run[best].pos], sizeof(Relation), retAddr);
   180			run[best].pos++;
   181	
   182			if (!refillRun(buf, run[best]))
   183				return -1;
   184		}
   185	
   186		pushToWrite(buf, NULL, 0, retAddr, false, true);
   187	
   188		return (int)(buf->numIO - startIO);
   189	}
