    15	
    16	/* Block nested loop join of R and S on R.A = S.C.
    17	 *
    18	 * R is the outer relation and is read in batches of M - 1 blocks; the last
    19	 * block of the buffer is used for the block of S that is currently probed
    20	 * against the batch, respectively for the block of the result that is being
    21	 * filled. Every batch of R therefore causes one complete scan of S.
    22	 *
    23	 * The joined tuples (A, B, D) are written to the chain of blocks starting at
    24	 * NLJ_RET_ADDR. The return value is the number of joined tuples, or -1 on
    25	 * failure.
    26	 */
    27	int nestedLoopJoin(Buffer *buf)
    28	{
    29		if (buf == NULL)
    30			return -1;
    31	
    32		int M = (int)buf->numAllBlk;
    33		if (M > MAX_BLK_IN_BUF)
    34			M = MAX_BLK_IN_BUF;
    35		if (M < 2)
    36			return -1;
    37	
    38		const int outerBlkNum = M - 1; /* blocks of R buffered at the same time */
    39	
    40		Relation outer[(MAX_BLK_IN_BUF - 1) * TUPLE_PER_BLK]; /* the current batch */
    41		Relation tuples[TUPLE_PER_BLK];
    42		int num = 0; /* number of joined tuples */
    43	
    44		cout << "select R.A, R.B, S.D from R, S where R.A = S.C (nested loop join):" << endl;
    45	
    46		pushToWrite(buf, NULL, 0, NLJ_RET_ADDR, true);
    47	
    48		for (int base = 0; base < R_BLK_NUM; base += outerBlkNum)
    49		{
    50			/* ---- outer scan: fill the buffer with the next M - 1 blocks of R ---- */
    51			int outerNum = 0;
    52	
    53			for (int i = 0; i < outerBlkNum && base + i < R_BLK_NUM; i++)
    54			{
    55				unsigned char *blk = readBlockFromDisk(R_ADDR + base + i, buf);
    56				if (blk == NULL)
    57					return -1;
    58	
    59				readTuplesFromBlock(blk, tuples);
