    61	
    62				for (int j = 0; j < TUPLE_PER_BLK; j++)
    63					if (tuples[j].attr1 != 0) /* 0 marks an unused tuple slot */
    64						outer[outerNum++] = tuples[j];
    65			}
    66	
    67			/* ---- inner probe: one complete scan of S against the batch ---- */
    68			for (int k = 0; k < S_BLK_NUM; k++)
    69			{
    70				unsigned char *blk = readBlockFromDisk(S_ADDR + k, buf);
    71				if (blk == NULL)
    72					return -1;
    73	
    74				readTuplesFromBlock(blk, tuples);
    75				freeBlockInBuffer(blk, buf);
    76	
    77				for (int i = 0; i < outerNum; i++)
    78				{
    79					for (int j = 0; j < TUPLE_PER_BLK; j++)
    80					{
    81						if (tuples[j].attr1 == 0) /* unused tuple slot */
    82							continue;
    83						if (outer[i].attr1 != tuples[j].attr1) /* R.A = S.C */
    84							continue;
    85	
    86						output(buf, NLJ_RET_ADDR, outer[i].attr1, outer[i].attr2, tuples[j].attr2);
