    41		Relation tuples[TUPLE_PER_BLK];
    42		unsigned int addr = MERGE_R_RET_ADDR;
    43		int num = 0;    /* number of distinct values found so far */
    44		int last = 0;   /* the value emitted last; 0 never occurs in R */
    45	
    46		while (addr != 0)
    47		{
    48			unsigned char *blk = readBlockFromDisk(addr, buf);
    49			if (blk == NULL)
    50				return -1;
    51	
    52			readTuplesFromBlock(blk, tuples);
    53			memcpy(&addr, blk + buf->blkSize - PTR_SIZE, PTR_SIZE); /* next block */
    54			freeBlockInBuffer(blk, buf);
    55	
    56			for (int j = 0; j < TUPLE_PER_BLK; j++)
    57			{
    58				if (tuples[j].attr1 == 0) /* unused tuple slot */
    59					continue;
    60				if (num > 0 && tuples[j].attr1 == last) /* duplicate of A */
