#include <iostream>
#include <string.h>
#include <unistd.h>
#include "join.h"
#include "file.h"
#include "blkio.h"

using namespace std;

/* Number of blocks the buffer can hold at the same time, i.e. M. */
#define MAX_BLK_IN_BUF (BUF_SIZE / (BLK_SIZE + 1))

/* Distance between the first blocks of two consecutive buckets on the disk. */
#define BUCKET_STRIDE (OFFSET / BUCKET_NUM)

/* Partition one relation into BUCKET_NUM buckets on the disk.
 *
 * The relation is scanned block by block; every tuple is handed to the hash
 * partition writer, which keeps one block per bucket in the buffer and flushes
 * it as soon as it is full. Only one block of the relation plus the BUCKET_NUM
 * bucket blocks are needed in the buffer at a time.
 *
 * The return value is the number of partitioned tuples, or -1 on failure.
 */
static int partition(Buffer *buf, unsigned int srcAddr, int srcBlkNum, unsigned int dstAddr)
{
	Relation tuples[TUPLE_PER_BLK];
	int num = 0;

	pushHashToWrite(buf, NULL, dstAddr, true); /* open the buckets of dstAddr */

	for (int i = 0; i < srcBlkNum; i++)
	{
		unsigned char *blk = readBlockFromDisk(srcAddr + i, buf);
		if (blk == NULL)
			return -1;

		readTuplesFromBlock(blk, tuples);
		freeBlockInBuffer(blk, buf); /* the tuples have been copied out */

		for (int j = 0; j < TUPLE_PER_BLK; j++)
		{
			if (tuples[j].attr1 == 0) /* 0 marks an unused tuple slot */
				continue;

			/* The writer hashes on the join attribute (tuple.attr1). */
			pushHashToWrite(buf, &tuples[j], dstAddr);
			num++;
		}
	}

	/* Write the last block of every bucket. */
	pushHashToWrite(buf, NULL, dstAddr, false, true);

	return num;
}

/* Hash join of R and S on R.A = S.C.
 *
 * phase 1: both relations are partitioned into BUCKET_NUM buckets with the same
 *          hash function (key mod BUCKET_NUM), so that a tuple of R can only
 *          join with tuples of S that live in the very same bucket,
 * phase 2: bucket by bucket, the tuples of R are loaded into the buffer and the
 *          tuples of S are read block by block and probed against them.
 *
 * The joined tuples (A, B, D) are written to the chain of blocks starting at
 * HJ_RET_ADDR. The return value is the number of joined tuples, or -1 on
 * failure.
 */
int hashJoin(Buffer *buf)
{
	if (buf == NULL)
		return -1;

	int M = (int)buf->numAllBlk;
	if (M > MAX_BLK_IN_BUF)
		M = MAX_BLK_IN_BUF;
	if (M < BUCKET_NUM + 1) /* one block per bucket plus the block scanned */
		return -1;

	cout << "select R.A, R.B, S.D from R, S where R.A = S.C (hash join):" << endl;

	/* --------- phase 1: partition both relations into the buckets --------- */
	if (partition(buf, R_ADDR, R_BLK_NUM, HASH_R_ADDR) < 0)
		return -1;
	if (partition(buf, S_ADDR, S_BLK_NUM, HASH_S_ADDR) < 0)
		return -1;

	return 0;
}

