//
// Created by zl on 2023-12-11.
//

#include <iostream>
#include <string.h>
#include "join.h"
#include "file.h"
#include "blkio.h"
#include "mergeSort.h"

using namespace std;

/* Number of blocks the buffer can hold at the same time, i.e. M. */
#define MAX_BLK_IN_BUF (BUF_SIZE / (BLK_SIZE + 1))

/* One of the two sorted relations while it is scanned by the merge. Exactly one
 * block of the relation is held in the buffer at a time, so the whole join only
 * needs three blocks: one per relation plus the block of the result. */
struct Scan
{
	unsigned char *blk;            /* block of the relation in the buffer */
	Relation tuple[TUPLE_PER_BLK]; /* the tuples stored in that block */
	int cnt;                       /* number of valid tuples in the block */
	int pos;                       /* the tuple the scan currently is at */
	unsigned int next;             /* address of the next block of the chain */
};

static void initScan(Scan &scan)
{
	scan.blk = NULL;
	scan.cnt = scan.pos = 0;
	scan.next = 0;
}

/* Read one block of the sorted relation into the buffer and decode it. */
static bool loadScanBlock(Buffer *buf, Scan &scan, unsigned int addr)
{
	if ((scan.blk = readBlockFromDisk(addr, buf)) == NULL)
		return false;

	readTuplesFromBlock(scan.blk, scan.tuple);

	scan.cnt = 0;
	while (scan.cnt < TUPLE_PER_BLK && scan.tuple[scan.cnt].attr1 != 0)
		scan.cnt++; /* 0 marks an unused tuple slot */
	scan.pos = 0;
	memcpy(&scan.next, scan.blk + buf->blkSize - PTR_SIZE, PTR_SIZE);

	return true;
}

/* Whether the scan currently is at a tuple. */
static bool scanHasTuple(const Scan &scan)
{
	return scan.blk != NULL && scan.pos < scan.cnt;
}

/* The key (the join attribute) the scan currently is at. */
static int scanKey(const Scan &scan)
{
	return scan.tuple[scan.pos].attr1;
}

/* Release an exhausted block and pull the next block of the relation in, so
 * that the scan is at a tuple again (unless the relation is over). */
static bool refillScan(Buffer *buf, Scan &scan)
{
	while (scan.blk != NULL && scan.pos >= scan.cnt)
	{
		unsigned int next = scan.next;

		freeBlockInBuffer(scan.blk, buf);
		scan.blk = NULL;
		scan.cnt = scan.pos = 0;

		if (next == 0) /* the chain of the relation ends here */
			break;
		if (!loadScanBlock(buf, scan, next))
			return false;
	}

	return true;
}

/* Give the block of a scan that is not needed any more back to the buffer. */
static void closeScan(Buffer *buf, Scan &scan)
{
	if (scan.blk != NULL)
		freeBlockInBuffer(scan.blk, buf);
	initScan(scan);
}

/* Step to the next tuple of the scan, reading the next block if needed. */
static bool nextTuple(Buffer *buf, Scan &scan)
{
	scan.pos++;
	return refillScan(buf, scan);
}

/* Sort merge join of R and S on R.A = S.C.
 *
 * preparation: both relations are sorted on the join attribute with the
 *              two-pass multi-way merge sort,
 * merge scan:  the two sorted relations are scanned side by side; whenever the
 *              two scans are at the same key, all the tuples of R and all the
 *              tuples of S that carry that key are joined with each other.
 *
 * The joined tuples (A, B, D) are written to the chain of blocks starting at
 * SMJ_RET_ADDR. The return value is the number of joined tuples, or -1 on
 * failure.
 */
int sortMergeJoin(Buffer *buf)
{
	if (buf == NULL)
		return -1;

	int M = (int)buf->numAllBlk;
	if (M > MAX_BLK_IN_BUF)
		M = MAX_BLK_IN_BUF;
	if (M < 3) /* one block per relation plus the block of the result */
		return -1;

	cout << "select R.A, R.B, S.D from R, S where R.A = S.C (sort merge join):" << endl;

	/* ---- preparation: sort both relations on the join attribute ---- */
	if (mergeSort(buf, SORT_R) < 0)
		return -1;
	if (mergeSort(buf, SORT_S) < 0)
		return -1;

	pushToWrite(buf, NULL, 0, SMJ_RET_ADDR, true);

	/* Open both sorted relations, i.e. read their first blocks. */
	Scan r, s;
	initScan(r);
	initScan(s);

	if (!loadScanBlock(buf, r, MERGE_R_RET_ADDR) || !refillScan(buf, r))
		return -1;
	if (!loadScanBlock(buf, s, MERGE_S_RET_ADDR) || !refillScan(buf, s))
		return -1;

	/* ---- merge scan: walk both relations with one pass over each ---- */

	/* All the tuples of S that share one key are kept in the buffer while they
	 * are joined, which is what makes one pass over each relation enough. */
	Relation group[(MAX_BLK_IN_BUF - 3) * TUPLE_PER_BLK];
	int num = 0; /* number of joined tuples */

	while (scanHasTuple(r) && scanHasTuple(s))
	{
		if (scanKey(r) < scanKey(s)) /* this tuple of R has no match */
		{
			if (!nextTuple(buf, r))
				return -1;
			continue;
		}

		if (scanKey(r) > scanKey(s)) /* this tuple of S has no match */
		{
			if (!nextTuple(buf, s))
				return -1;
			continue;
		}

		/* R.A = S.C: collect the whole group of S that carries the key ... */
		int key = scanKey(s);
		int groupNum = 0;

		while (scanHasTuple(s) && scanKey(s) == key)
		{
			if (groupNum >= (int)(sizeof(group) / sizeof(group[0])))
			{
				perror("Duplicate Group Overflows!\n");
				return -1;
			}

			group[groupNum++] = s.tuple[s.pos];

			if (!nextTuple(buf, s))
				return -1;
		}

		/* ... and join every tuple of R that carries it with the group. */
		while (scanHasTuple(r) && scanKey(r) == key)
		{
			for (int i = 0; i < groupNum; i++)
			{
				output(buf, SMJ_RET_ADDR, r.tuple[r.pos].attr1, r.tuple[r.pos].attr2, group[i].attr2);
				num++;
			}

			if (!nextTuple(buf, r))
				return -1;
		}
	}

	/* The tuples behind the end of the other relation cannot join any more. */
	closeScan(buf, r);
	closeScan(buf, s);

	/* Write the last, partially filled block of the result. */
	pushToWrite(buf, NULL, 0, SMJ_RET_ADDR, false, true);

	cout << "Total number of result tuples: " << num << endl;
	cout << "Total number of I/O's: " << buf->numIO << endl;

	return num;
}

