/* One of the two sorted relations while it is scanned by the merge. Exactly one
 * block of the relation is held in the buffer at a time, so the whole join only
 * needs three blocks: one per relation plus the block of the result. */
struct Scan
{
	unsigned char *blk;            /* block of the relation in the buffer */
	Relation tuple[TUPLE_PER_BLK]; /* the tuples stored in that block */
	int cnt;                       /* number of valid tuples in the block */
	int pos;                       /* the tuple the scan currently is at */
	unsigned int next;             /* address of the next block of the chain */
};

static void initScan(Scan &scan)
{
	scan.blk = NULL;
	scan.cnt = scan.pos = 0;
	scan.next = 0;
}

/* Read one block of the sorted relation into the buffer and decode it. */
static bool loadScanBlock(Buffer *buf, Scan &scan, unsigned int addr)
{
	if ((scan.blk = readBlockFromDisk(addr, buf)) == NULL)
		return false;

	readTuplesFromBlock(scan.blk, scan.tuple);

	scan.cnt = 0;
	while (scan.cnt < TUPLE_PER_BLK && scan.tuple[scan.cnt].attr1 != 0)
		scan.cnt++; /* 0 marks an unused tuple slot */
	scan.pos = 0;
	memcpy(&scan.next, scan.blk + buf->blkSize - PTR_SIZE, PTR_SIZE);

	return true;
}

/* Whether the scan currently is at a tuple. */
static bool scanHasTuple(const Scan &scan)
{
	return scan.blk != NULL && scan.pos < scan.cnt;
}

/* Release an exhausted block and pull the next block of the relation in, so
 * that the scan is at a tuple again (unless the relation is over). */
static bool refillScan(Buffer *buf, Scan &scan)
{
	while (scan.blk != NULL && scan.pos >= scan.cnt)
	{
		unsigned int next = scan.next;

		freeBlockInBuffer(scan.blk, buf);
		scan.blk = NULL;
		scan.cnt = scan.pos = 0;

		if (next == 0) /* the chain of the relation ends here */
			break;
		if (!loadScanBlock(buf, scan, next))
			return false;
	}

	return true;
}

/* Give the block of a scan that is not needed any more back to the buffer. */
static void closeScan(Buffer *buf, Scan &scan)
{
	if (scan.blk != NULL)
		freeBlockInBuffer(scan.blk, buf);
	initScan(scan);
}

