/* Split a query into its tokens: the parts of a query are separated by blanks,
 * i.e. "SELECT", "[", "ENAME", "=", "'Mary'", ... */
static vector<string> tokenize(const string &query)
{
	vector<string> token;
	size_t i = 0;

	while (i < query.length()) {
		while (i < query.length() && isspace((unsigned char)query[i]))
			i++; // skip the blanks in front of the token

		size_t begin = i;
		while (i < query.length() && !isspace((unsigned char)query[i]))
			i++;

		if (i > begin)
			token.push_back(query.substr(begin, i - begin));
	}

	return token;
}

static TreeNode *parseExpression(const vector<string> &token, size_t &pos);

/* The information a SELECT or a PROJECTION node carries is written in brackets,
 * e.g. "[ ENAME = 'Mary' & DNAME = 'Research' ]" or "[ ESSN, PNAME ]". The
 * brackets themselves are dropped, the tokens in between are kept verbatim. */
static string parseInfo(const vector<string> &token, size_t &pos)
{
	string info;

	if (pos >= token.size() || token[pos] != "[")
		return info;

	pos++; // skip "["
	while (pos < token.size() && token[pos] != "]") {
		if (!info.empty())
			info += " ";
		info += token[pos++];
	}
	if (pos < token.size())
		pos++; // skip "]"

	return info;
}

/* An operand of a query:
 *   SELECT [ condition ] ( expression )
 *   PROJECTION [ attributes ] ( expression )
 *   ( expression )
 *   the name of a relation
 */
static TreeNode *parseOperand(const vector<string> &token, size_t &pos)
{
	if (pos >= token.size())
		return NULL;

	string type = token[pos];

	if (type == "SELECT" || type == "PROJECTION") {
		pos++;

		TreeNode *node = new TreeNode(type, parseInfo(token, pos));

		// the operator is applied to the expression in the parentheses
		if (pos < token.size() && token[pos] == "(") {
			pos++;
			node->left = parseExpression(token, pos);
			if (pos < token.size() && token[pos] == ")")
				pos++;
		} else {
			node->left = parseOperand(token, pos);
		}

		return node;
	}

	if (type == "(") {
		pos++;

		TreeNode *node = parseExpression(token, pos);
		if (pos < token.size() && token[pos] == ")")
			pos++;

		return node;
	}

	pos++; // everything else is the name of a relation

	return new TreeNode("LEAF", type);
}

/* A query is an operand, possibly joined with further operands:
 *   expression := operand { JOIN operand }
 * A join of more than two relations becomes a left deep tree of JOIN nodes. */
static TreeNode *parseExpression(const vector<string> &token, size_t &pos)
{
	TreeNode *node = parseOperand(token, pos);

	while (pos < token.size() && token[pos] == "JOIN") {
		pos++;

		TreeNode *join = new TreeNode("JOIN");
		join->left = node;
		join->right = parseOperand(token, pos);
		node = join;
	}

	return node;
}

void parseQuery(TreeNode *root, string query)
{
	if (root == NULL)
		return;

	vector<string> token = tokenize(query);
	size_t pos = 0;

	// the root node does not store any information: the tree of the query is
	// built below it
	root->left = parseExpression(token, pos);
	root->right = NULL;
}

TreeNode *optimizeQuery(TreeNode *root, vector<string> info)
{
	/* TODO: implement */
	return root;
}

