// Standalone structural harness for the QueryOptimize lab. Not part of the lab
// build: it links the lab's main.cpp with main() renamed away, so the parse and
// the optimisation can be inspected independently of TreeNode::preOrder.
//
// Build: see agent_tests/run_optimize_checks.sh
#include <iostream>
#include <string>
#include <vector>
#include "../lab/QueryOptimize/tree.h"

using namespace std;

void parseQuery(TreeNode *root, string query);
TreeNode *optimizeQuery(TreeNode *root, vector<string> info);

/* One line per node: <indent><type>|<info> so that the structure of the tree can
 * be compared without depending on the format preOrder prints. */
static void dump(TreeNode *node, int level)
{
	for (int i = 0; i < level; i++)
		cout << "  ";

	if (node == NULL) {
		cout << "(null)" << endl;
		return;
	}

	cout << node->type << "|" << node->info << endl;

	if (node->left != NULL)
		dump(node->left, level + 1);
	if (node->right != NULL)
		dump(node->right, level + 1);
}

int main()
{
	string query[3] = {
		"SELECT [ ENAME = 'Mary' & DNAME = 'Research' ] ( EMPLOYEE JOIN DEPARTMENT )",
		"PROJECTION [ BDATE ] ( SELECT [ ENAME = 'John' & DNAME = 'Research' ] ( EMPLOYEE JOIN DEPARTMENT ) )",
		"SELECT [ ESSN = '01' ] ( PROJECTION [ ESSN, PNAME ] ( WORKS_ON JOIN PROJECT ) )",
	};

	// extra queries that are not part of main(): they exercise the parser and
	// the optimiser beyond the three built-in cases
	string extra[4] = {
		"SELECT [ ENAME = 'Mary' ] ( EMPLOYEE )",
		"PROJECTION [ ENAME ] ( SELECT [ SALARY > 30000 & DNAME = 'Research' & PNAME = 'ProductX' ] ( EMPLOYEE JOIN DEPARTMENT JOIN PROJECT ) )",
		"SELECT [ EMPLOYEE.DNO = DEPARTMENT.DNUMBER ] ( EMPLOYEE JOIN DEPARTMENT )",
		"SELECT [ UNKNOWNATTR = '7' ] ( EMPLOYEE JOIN DEPARTMENT )",
